          <Button
            id="confirm-approve-btn"
            onClick={onConfirm}
            disabled={!agreed || isLoading}
            className="gap-2 bg-emerald-700 hover:bg-emerald-800 text-white"
          >
            {isLoading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <ShieldCheck className="h-4 w-4" />
            )}
            Approve &amp; Integrate
          </Button>
        </div>
      </div>
    </div>
  );
}

