"use client";

/**
 * components/canvas/ReflectionCanvas.tsx
 *
 * Responsive, iPad-optimised reflection and journaling canvas.
 *
 * ─── Pointer Events engine ────────────────────────────────────────────────
 * Uses native Pointer Events (not mouse / touch events) for:
 *   • Unified stylus + touch + mouse handling
 *   • Per-pointer pressure (e.pressure) mapped to stroke width
 *   • Stylus detection: e.pointerType === 'pen'
 *   • Palm rejection: CSS `touch-action: none` + pointerId capture
 *
 * ─── Drawing model ────────────────────────────────────────────────────────
 *   strokes[]  — committed history (undo = pop, redo = push back)
 *   liveStroke — the stroke being drawn right now (not yet in history)
 *
 * ─── Export pipeline ──────────────────────────────────────────────────────
 *   exportVectorData()   → serialisable CanvasVectorData (for progressive saves)
 *   exportAsImageBlob()  → compressed PNG/JPEG Blob ≤ 2 MB at ≤ 1 200 px wide
 *   uploadReflection()   → calls Worker POST /reflections/upload → Supabase Storage
 *
 * ─── Architecture guardrails ──────────────────────────────────────────────
 *   • No localStorage / sessionStorage
 *   • All uploads go through the Cloudflare Worker (apiFetch) — never directly
 *     to Supabase Storage from the browser
 * ─────────────────────────────────────────────────────────────────────────
 */

import React, {
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import { apiFetch } from "@/lib/auth";
import { CLINICAL_AI_API_BASE } from "@/lib/clinical-ai-api";

import {
  Eraser,
  Loader2,
  Pen,
  Redo2,
  Trash2,
  Undo2,
  CheckCircle2,
  AlertTriangle,
} from "lucide-react";

import {
  BACKGROUND_OPTIONS,
  STROKE_WIDTHS,
  STYLUS_STROKE_SCALE,
  type BackgroundType,
  type CanvasVectorData,
  type DrawTool,
  type Point,
  type Stroke,
  type UploadResult,
} from "./canvasTypes";

import {
  exportAsImageBlob,
  newStrokeId,
  redrawAll,
  renderStroke,
  serialiseVectorData,
} from "./canvasUtils";

// ---------------------------------------------------------------------------
// Imperative handle — exposed via ref
// ---------------------------------------------------------------------------

export interface ReflectionCanvasHandle {
  /** Returns the serialisable vector data (for progressive saves). */
  exportVectorData: () => CanvasVectorData;
  /** Compresses the canvas to a PNG/JPEG Blob ≤ 2 MB. */
  exportAsImageBlob: () => Promise<Blob>;
  /** Full pipeline: compress → upload to Supabase Storage via Worker. */
  uploadReflection: (submissionId: string, clientId: string) => Promise<UploadResult>;
  /** Returns true if the canvas has any drawn content. */
  hasContent: () => boolean;
}

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

interface ReflectionCanvasProps {
  /** Initial vector data to restore (e.g. from a saved draft). */
  initialData?: CanvasVectorData;
  /** Called on every committed stroke — for auto-save of vector data. */
  onStrokeCommit?: (data: CanvasVectorData) => void;
  /** CSS class forwarded to the root container. */
  className?: string;
  /** Identifies the owning client for the reflection. */
  clientId?: string;
  /** Optional submissionId linking this reflection to a practice task submission. */
  submissionId?: string | null;
}

// ---------------------------------------------------------------------------
// Pen colour
// ---------------------------------------------------------------------------

const PEN_COLOR = "#1a1d28"; // near-black ink — adapts via compositing in dark mode

// ---------------------------------------------------------------------------
// Toolbar button primitive
// ---------------------------------------------------------------------------

interface ToolbarBtnProps {
  label: string;
  active?: boolean;
  danger?: boolean;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}

function ToolbarBtn({ label, active, danger, disabled, onClick, children }: ToolbarBtnProps) {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      aria-pressed={active}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        "relative flex h-10 w-10 items-center justify-center rounded-xl transition-all duration-150",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-400",
        "disabled:pointer-events-none disabled:opacity-35",
        active
          ? "bg-slate-800 text-white shadow-inner"
          : danger
          ? "text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/50"
          : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-700/60"
      )}
    >
      {children}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Toolbar separator
// ---------------------------------------------------------------------------

function ToolbarSep() {
  return (
    <div className="mx-0.5 h-6 w-px bg-slate-200 dark:bg-slate-700" role="separator" />
  );
}

// ---------------------------------------------------------------------------
// Status pill
// ---------------------------------------------------------------------------

type UploadStatus = "idle" | "compressing" | "uploading" | "done" | "error";

function StatusPill({ status, error }: { status: UploadStatus; error?: string }) {
  if (status === "idle") return null;

  const configs: Record<
    Exclude<UploadStatus, "idle">,
    { icon: React.ReactNode; text: string; cls: string }
  > = {
    compressing: {
      icon: <Loader2 className="h-3.5 w-3.5 animate-spin" />,
      text: "Compressing…",
      cls: "bg-amber-100 text-amber-800 dark:bg-amber-950/60 dark:text-amber-300",
    },
    uploading: {
      icon: <Loader2 className="h-3.5 w-3.5 animate-spin" />,
      text: "Uploading…",
      cls: "bg-blue-100 text-blue-800 dark:bg-blue-950/60 dark:text-blue-300",
    },
    done: {
      icon: <CheckCircle2 className="h-3.5 w-3.5" />,
      text: "Saved",
      cls: "bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300",
    },
    error: {
      icon: <AlertTriangle className="h-3.5 w-3.5" />,
      text: error ?? "Upload failed",
      cls: "bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-300",
    },
  };

  const { icon, text, cls } = configs[status];

  return (
    <div
      role={status === "error" ? "alert" : "status"}
      aria-live="polite"
      className={cn(
        "flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium",
        cls
      )}
    >
      {icon}
      <span>{text}</span>
    </div>
  );
}

// ---------------------------------------------------------------------------
// ReflectionCanvas
// ---------------------------------------------------------------------------

const ReflectionCanvas = React.forwardRef<
  ReflectionCanvasHandle,
  ReflectionCanvasProps
>(function ReflectionCanvas({ initialData, onStrokeCommit, className, clientId, submissionId }, ref) {
  // ── Canvas refs ──────────────────────────────────────────────────────────
  const canvasRef    = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // ── Drawing state ────────────────────────────────────────────────────────
  const [tool,       setTool]       = useState<DrawTool>("pen");
  const [strokePxIdx, setStrokePxIdx] = useState(1);          // index into STROKE_WIDTHS
  const [background, setBackground] = useState<BackgroundType>(
    initialData?.background ?? "blank"
  );
  const [isDark, setIsDark]         = useState(false);

  // Committed history + redo stack — kept in refs to avoid re-render churn.
  // DELIBERATE LIMITATION (lint rank 8c): `initialData` is read once, at mount, and never
  // re-synced afterwards — here, in `background` above, or anywhere else. That is the intended
  // contract for a drawing surface: the undo/redo stacks are per-session state, so adopting new
  // props mid-flight would silently discard the user's in-progress strokes. A parent that needs
  // to load a different document must remount this component with a `key`.
  const strokesRef = useRef<Stroke[]>(initialData?.strokes ?? []);
  const redoRef    = useRef<Stroke[]>([]);

  // Live stroke being drawn
  const liveStrokeRef = useRef<Stroke | null>(null);

  // Whether any pointer is currently down (for palm rejection)
  const activePointerRef = useRef<number | null>(null);

  // Force re-render only for UI counters (undo/redo availability).
  // Seeded from the prop, never from `strokesRef`: a ref read in a render-path initialiser
  // is a `react-hooks/refs` violation, and the prop is the same source this ref was seeded
  // from (B16, lint rank 8c).
  const [historyLen, setHistoryLen] = useState(() => initialData?.strokes?.length ?? 0);
  const [redoLen,    setRedoLen]    = useState(0);

  // ── Upload state ─────────────────────────────────────────────────────────
  const [uploadStatus, setUploadStatus] = useState<UploadStatus>("idle");
  const [uploadError,  setUploadError]  = useState<string | undefined>();

  // ── Dark mode detection ──────────────────────────────────────────────────
  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    setIsDark(mq.matches);
    const handler = (e: MediaQueryListEvent) => setIsDark(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  // ── Canvas sizing (ResizeObserver) ───────────────────────────────────────
  useEffect(() => {
    const container = containerRef.current;
    const canvas    = canvasRef.current;
    if (!container || !canvas) return;

    const ro = new ResizeObserver((entries) => {
      const { width, height } = entries[0].contentRect;
      if (!width || !height) return;

      // Preserve content across resize using an offscreen snapshot
      const tempCanvas  = document.createElement("canvas");
      tempCanvas.width  = canvas.width;
      tempCanvas.height = canvas.height;
      const tempCtx     = tempCanvas.getContext("2d")!;
      tempCtx.drawImage(canvas, 0, 0);

      // Resize (this clears the canvas)
      const dpr    = window.devicePixelRatio || 1;
      canvas.width  = width  * dpr;
      canvas.height = height * dpr;
      canvas.style.width  = `${width}px`;
      canvas.style.height = `${height}px`;

      const ctx = canvas.getContext("2d")!;
      ctx.scale(dpr, dpr);

      // Full redraw from vector data
      redrawAll(
        ctx,
        width,
        height,
        background,
        strokesRef.current,
        isDark
      );
    });

    ro.observe(container);
    return () => ro.disconnect();
    // background / isDark changes handled separately below
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Redraw on background or dark-mode change ─────────────────────────────
  const redrawCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d")!;
    const dpr = window.devicePixelRatio || 1;
    redrawAll(
      ctx,
      canvas.width  / dpr,
      canvas.height / dpr,
      background,
      strokesRef.current,
      isDark
    );
  }, [background, isDark]);

  useEffect(() => { redrawCanvas(); }, [redrawCanvas]);

  // ── DPR-aware coordinate helper ──────────────────────────────────────────
  const toCanvasCoords = useCallback(
    (e: PointerEvent): Point => {
      const canvas = canvasRef.current!;
      const rect   = canvas.getBoundingClientRect();
      return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        pressure: e.pressure > 0 ? e.pressure : undefined,
      };
    },
    []
  );

  // ── Effective stroke width (accounts for stylus scale + tool) ────────────
  const effectiveWidth = useCallback(
    (e: PointerEvent): number => {
      const base = STROKE_WIDTHS[strokePxIdx].px;
      if (tool === "eraser") return base * 4;      // eraser is always fat
      return e.pointerType === "pen"
        ? base * STYLUS_STROKE_SCALE
        : base;
    },
    [tool, strokePxIdx]
  );

  // ── Pointer event handlers ────────────────────────────────────────────────
  const handlePointerDown = useCallback(
    (e: PointerEvent) => {
      // Palm rejection: only one active pointer at a time
      if (activePointerRef.current !== null) return;

      // Only accept pen or mouse; reject bare-finger touch that looks like a palm
      if (e.pointerType === "touch" && e.width > 50) return; // fat contact = palm

      e.preventDefault();
      canvasRef.current?.setPointerCapture(e.pointerId);
      activePointerRef.current = e.pointerId;

      const pt = toCanvasCoords(e);
      const stroke: Stroke = {
        id:     newStrokeId(),
        tool,
        color:  PEN_COLOR,
        width:  effectiveWidth(e),
        points: [pt],
      };
      liveStrokeRef.current = stroke;

      // Draw the starting dot
      const canvas = canvasRef.current!;
      const ctx    = canvas.getContext("2d")!;
      renderStroke(ctx, stroke);
    },
    [tool, toCanvasCoords, effectiveWidth]
  );

  const handlePointerMove = useCallback(
    (e: PointerEvent) => {
      if (activePointerRef.current !== e.pointerId) return;
      if (!liveStrokeRef.current) return;

      e.preventDefault();

      const pt     = toCanvasCoords(e);
      const stroke = liveStrokeRef.current;
      stroke.points.push(pt);

      // Incremental render: just draw the latest segment
      const canvas = canvasRef.current!;
      const ctx    = canvas.getContext("2d")!;
      renderStroke(ctx, { ...stroke, points: stroke.points.slice(-3) });
    },
    [toCanvasCoords]
  );

  const handlePointerUp = useCallback(
    (e: PointerEvent) => {
      if (activePointerRef.current !== e.pointerId) return;

      e.preventDefault();
      canvasRef.current?.releasePointerCapture(e.pointerId);
      activePointerRef.current = null;

      const stroke = liveStrokeRef.current;
      if (!stroke || stroke.points.length < 1) {
        liveStrokeRef.current = null;
        return;
      }

      // Commit stroke to history
      strokesRef.current = [...strokesRef.current, stroke];
      redoRef.current    = [];                              // any redo branch is lost
      liveStrokeRef.current = null;

      setHistoryLen(strokesRef.current.length);
      setRedoLen(0);

      // Notify parent for progressive save
      const canvas = canvasRef.current!;
      const dpr    = window.devicePixelRatio || 1;
      onStrokeCommit?.(
        serialiseVectorData(
          canvas.width  / dpr,
          canvas.height / dpr,
          background,
          strokesRef.current
        )
      );
    },
    [background, onStrokeCommit]
  );

  // ── Attach / detach pointer listeners on canvas ──────────────────────────
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    canvas.addEventListener("pointerdown", handlePointerDown);
    canvas.addEventListener("pointermove", handlePointerMove);
    canvas.addEventListener("pointerup",   handlePointerUp);
    canvas.addEventListener("pointercancel", handlePointerUp);

    return () => {
      canvas.removeEventListener("pointerdown", handlePointerDown);
      canvas.removeEventListener("pointermove", handlePointerMove);
      canvas.removeEventListener("pointerup",   handlePointerUp);
      canvas.removeEventListener("pointercancel", handlePointerUp);
    };
  }, [handlePointerDown, handlePointerMove, handlePointerUp]);

  // ── Undo ─────────────────────────────────────────────────────────────────
  const handleUndo = useCallback(() => {
    if (!strokesRef.current.length) return;
    const popped = strokesRef.current[strokesRef.current.length - 1];
    strokesRef.current = strokesRef.current.slice(0, -1);
    redoRef.current    = [popped, ...redoRef.current];
    setHistoryLen(strokesRef.current.length);
    setRedoLen(redoRef.current.length);
    redrawCanvas();
  }, [redrawCanvas]);

  // ── Redo ─────────────────────────────────────────────────────────────────
  const handleRedo = useCallback(() => {
    if (!redoRef.current.length) return;
    const [next, ...rest] = redoRef.current;
    strokesRef.current = [...strokesRef.current, next];
    redoRef.current    = rest;
    setHistoryLen(strokesRef.current.length);
    setRedoLen(redoRef.current.length);
    redrawCanvas();
  }, [redrawCanvas]);

  // ── Clear ─────────────────────────────────────────────────────────────────
  const handleClear = useCallback(() => {
    strokesRef.current = [];
    redoRef.current    = [];
    setHistoryLen(0);
    setRedoLen(0);
    redrawCanvas();
  }, [redrawCanvas]);

  // ── Keyboard shortcuts ────────────────────────────────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target !== document.body && e.target !== document.documentElement) return;
      if ((e.metaKey || e.ctrlKey) && e.key === "z") {
        if (e.shiftKey) handleRedo();
        else handleUndo();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [handleUndo, handleRedo]);

  // ── Imperative handle ─────────────────────────────────────────────────────
  // `clientId` / `submissionId` are dependencies because `uploadReflection()` falls back to
  // the closed-over props when called with no arguments (`submissionIdParam || submissionId`).
  // Without them the handle would keep using the props as of the last `background` change and
  // could attach a reflection image to the wrong client or submission (B1, lint rank 8c).
  useImperativeHandle(ref, () => ({
    exportVectorData(): CanvasVectorData {
      const canvas = canvasRef.current!;
      const dpr    = window.devicePixelRatio || 1;
      return serialiseVectorData(
        canvas.width  / dpr,
        canvas.height / dpr,
        background,
        strokesRef.current
      );
    },

    async exportAsImageBlob(): Promise<Blob> {
      return exportAsImageBlob(canvasRef.current!);
    },

    async uploadReflection(
      submissionIdParam?: string,
      clientIdParam?: string
    ): Promise<UploadResult> {
      const activeSubmissionId = submissionIdParam || submissionId;
      const activeClientId = clientIdParam || clientId;
      if (!activeSubmissionId || !activeClientId) {
        throw new Error("Missing submissionId or clientId for reflection upload");
      }
      setUploadError(undefined);
      setUploadStatus("compressing");

      let blob: Blob;
      try {
        blob = await exportAsImageBlob(canvasRef.current!);
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Compression failed";
        setUploadError(msg);
        setUploadStatus("error");
        throw err;
      }

      setUploadStatus("uploading");

      try {
        const formData = new FormData();
        formData.append("file", blob, `reflection-${Date.now()}.png`);
        formData.append("submission_id", activeSubmissionId);
        formData.append("client_id",     activeClientId);

        const res = await apiFetch(
          `${CLINICAL_AI_API_BASE}/reflections/upload`,
          { method: "POST", body: formData }
        );

        if (!res.ok) {
          const body = await res.json().catch(() => null) as { error?: string } | null;
          throw new Error(body?.error ?? `HTTP ${res.status}`);
        }

        const result = await res.json() as UploadResult;
        setUploadStatus("done");
        return result;
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Upload failed";
        setUploadError(msg);
        setUploadStatus("error");
        throw err;
      }
    },

    hasContent(): boolean {
      return strokesRef.current.length > 0;
    },
  }), [background, clientId, submissionId]);

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div
      className={cn(
        "relative flex flex-col overflow-hidden rounded-xl border border-slate-200",
        "bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900",
        className
      )}
    >
      {/* ── Floating toolbar ──────────────────────────────────────────────── */}
      <div
        role="toolbar"
        aria-label="Drawing tools"
        className={cn(
          // Floating pill positioned at the top centre
          "absolute left-1/2 top-3 z-20 -translate-x-1/2",
          "flex items-center gap-0.5 rounded-xl px-2 py-1.5",
          "bg-white/90 shadow-lg shadow-slate-200/60 backdrop-blur-md",
          "border border-slate-100 dark:border-slate-700",
          "dark:bg-slate-800/90 dark:shadow-slate-900/60"
        )}
      >
        {/* Tool: Pen */}
        <ToolbarBtn
          label="Pen"
          active={tool === "pen"}
          onClick={() => setTool("pen")}
        >
          <Pen className="h-4 w-4" />
        </ToolbarBtn>

        {/* Tool: Eraser */}
        <ToolbarBtn
          label="Eraser"
          active={tool === "eraser"}
          onClick={() => setTool("eraser")}
        >
          <Eraser className="h-4 w-4" />
        </ToolbarBtn>

        <ToolbarSep />

        {/* Stroke width selector */}
        {STROKE_WIDTHS.map((sw, i) => (
          <ToolbarBtn
            key={sw.label}
            label={`Stroke: ${sw.label}`}
            active={tool !== "eraser" && strokePxIdx === i}
            onClick={() => { setStrokePxIdx(i); setTool("pen"); }}
          >
            <span
              className={cn(
                "block rounded-full bg-current transition-all",
                // Visually vary the dot size per width option
                i === 0 ? "h-1.5 w-1.5" : i === 1 ? "h-2.5 w-2.5" : "h-4 w-4"
              )}
            />
          </ToolbarBtn>
        ))}

        <ToolbarSep />

        {/* Background toggles */}
        {BACKGROUND_OPTIONS.map((bg) => (
          <ToolbarBtn
            key={bg.id}
            label={`Background: ${bg.label}`}
            active={background === bg.id}
            onClick={() => setBackground(bg.id)}
          >
            <span className="font-mono text-xs leading-none">{bg.icon}</span>
          </ToolbarBtn>
        ))}

        <ToolbarSep />

        {/* Undo */}
        <ToolbarBtn
          label={`Undo (${historyLen})`}
          disabled={historyLen === 0}
          onClick={handleUndo}
        >
          <Undo2 className="h-4 w-4" />
        </ToolbarBtn>

        {/* Redo */}
        <ToolbarBtn
          label={`Redo (${redoLen})`}
          disabled={redoLen === 0}
          onClick={handleRedo}
        >
          <Redo2 className="h-4 w-4" />
        </ToolbarBtn>

        <ToolbarSep />

        {/* Clear */}
        <ToolbarBtn
          label="Clear canvas"
          danger
          disabled={historyLen === 0}
          onClick={handleClear}
        >
          <Trash2 className="h-4 w-4" />
        </ToolbarBtn>

        {/* Upload status */}
        <div className="ml-1">
          <StatusPill status={uploadStatus} error={uploadError} />
        </div>
      </div>

      {/* ── Drawing surface ───────────────────────────────────────────────── */}
      <div
        ref={containerRef}
        className="relative flex-1"
        // Minimum height ensures canvas is usable before ResizeObserver fires
        style={{ minHeight: "420px" }}
      >
        <canvas
          ref={canvasRef}
          aria-label="Reflection canvas — use a stylus or finger to draw"
          style={{
            // Palm rejection: browser must not intercept pointer events
            touchAction: "none",
            // Crisp rendering for handwriting
            imageRendering: "pixelated",
            cursor: tool === "eraser" ? "cell" : "crosshair",
            display: "block",
            width:  "100%",
            height: "100%",
          }}
        />
      </div>

      {/* ── Bottom status bar ─────────────────────────────────────────────── */}
      <div
        className={cn(
          "flex items-center justify-between border-t border-slate-100 px-4 py-2",
          "bg-slate-50/80 dark:border-slate-700 dark:bg-slate-800/50"
        )}
      >
        <p className="text-[11px] text-slate-400 dark:text-slate-500">
          {historyLen === 0
            ? "Draw with a stylus, finger, or mouse"
            : `${historyLen} stroke${historyLen !== 1 ? "s" : ""}`}
        </p>
        <p className="text-[11px] text-slate-400 dark:text-slate-500">
          ⌘Z undo · ⌘⇧Z redo
        </p>
      </div>
    </div>
  );
});

ReflectionCanvas.displayName = "ReflectionCanvas";
export default ReflectionCanvas;
export type { ReflectionCanvasProps };

"use client"

import { useState, useEffect } from "react"
import { Loader2 } from "lucide-react"
import { CLINICAL_AI_API_BASE as API_BASE } from "@/lib/clinical-ai-api"
import { apiFetch } from "@/lib/auth"
import { Client } from "@/types";
import type { PracticePackage } from "@/lib/practice-package";
import type { StructuredTask } from "@/lib/ai/schemas";
import { DynamicTaskForm } from "@/components/tasks/DynamicTaskForm"

/**
 * `GET /client/history` returns `practice_package` in whichever shape the Worker
 * stored: a structured task (has `task_type`) or a PracticePackage from
 * `/generate/practice-package`.
 */
function isStructuredTask(
  pkg: StructuredTask | PracticePackage | null | undefined
): pkg is StructuredTask {
  return !!pkg && typeof pkg === "object" && "task_type" in pkg;
}

/** The three variants `DynamicTaskForm` renders — `reflection_prompt` uses the canvas instead. */
const FORM_TASK_TYPES = ["two_choice_worksheet", "activity_log", "thought_record"] as const;

/**
 * A structured task this component can render. The body proves the narrowing
 * (`isStructuredTask` plus the same three `task_type` literals the old filter used,
 * in the same order), so the claim is exactly what was checked.
 */
function isRenderableTask(
  pkg: StructuredTask | PracticePackage | null | undefined
): pkg is Extract<StructuredTask, { task_type: (typeof FORM_TASK_TYPES)[number] }> {
  return isStructuredTask(pkg) && FORM_TASK_TYPES.some((t) => t === pkg.task_type);
}

interface AssignedMaterial {
  id: string
  title?: string
  content: string
  scenario?: string
  skill?: string
  reflection?: string
  worksheetQuestions?: string[]
  createdAt?: string
  modality?: string
  practice_package?: StructuredTask | PracticePackage | null
}

export function ClientView({ client }: { client: Client }) {
  const CLIENT_ID = client.id;
  const [material, setMaterial] = useState<AssignedMaterial | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<Error | null>(null)

  useEffect(() => {
    setIsLoading(true)

    const fetchVignettes = async () => {
      try {
        const response = await apiFetch(`${API_BASE}/client/history?clientId=${CLIENT_ID}`)
        if (!response.ok) throw new Error("Failed to fetch")

        const data: AssignedMaterial[] = await response.json()

        // Find the newest material that is a worksheet
        const newest = data.find(m => isRenderableTask(m.practice_package))
        setMaterial(newest || null)
      } catch (err) {
        setError(err instanceof Error ? err : new Error("Unknown error"))
      } finally {
        setIsLoading(false)
      }
    }

    fetchVignettes()
  }, [CLIENT_ID])

  if (isLoading) {
    return (
      <main className="flex-1 flex items-center justify-center bg-background p-8 min-h-[50vh]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </main>
    )
  }

  if (error) {
    return (
      <main className="flex-1 overflow-auto bg-background p-8">
        <h2 className="text-xl mb-4">{client.name} — Materials</h2>
        <p className="text-rose-500">Error loading data</p>
      </main>
    )
  }

  if (!material || !isRenderableTask(material.practice_package)) {
    return (
      <main className="flex-1 flex items-center justify-center bg-background p-8 min-h-[50vh]">
        <div className="text-center">
          <h2 className="text-xl font-medium mb-2">No active worksheets</h2>
          <p className="text-muted-foreground">You have completed all assigned worksheets.</p>
        </div>
      </main>
    )
  }

  return (
    <main className="flex-1 overflow-auto bg-background p-0 sm:p-8">
      <DynamicTaskForm 
        clientId={CLIENT_ID}
        taskType={material.practice_package.task_type}
        initialData={material.practice_package}
        onSubmitted={() => {
          // Just remove it from view once submitted for now
          setMaterial(null)
        }}
        onCancel={() => {
          setMaterial(null)
        }}
      />
    </main>
  )
}

"use client";

import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { Sheet, SheetContent, SheetDescription, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Menu } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useClientNavStore } from "@/stores/useClientNavStore";

// Note that rem in a media query resolves against the initial font size, so 64rem and 1024px
// are the same boundary, and this string is byte-for-byte the one the compiled Tailwind sheet
// uses for .lg\:hidden / .lg\:flex.
const DESKTOP_QUERY = "(min-width: 64rem)";

export function DashboardShell({ viewMode, activeTab, onViewModeChange, onTabChange, children }: {
  viewMode: "clinician" | "client";
  activeTab: "vignette" | "summaries";
  onViewModeChange: (mode: "clinician" | "client") => void;
  onTabChange: (tab: "vignette" | "summaries") => void;
  children: React.ReactNode;
}) {
  const [drawerOpen, setDrawerOpen] = useState(false);
  // Start isMobile as false so the server render and the first client render agree - no hydration mismatch.
  const [isMobile, setIsMobile] = useState(false);

  const selectedClientId = useClientNavStore((s) => s.selectedClientId);
  const selectedSessionId = useClientNavStore((s) => s.selectedSessionId);

  const lastMobile = useRef(false);

  useEffect(() => {
    const query = window.matchMedia(DESKTOP_QUERY);

    const sync = () => {
      const next = !query.matches;
      // `resize` re-reads the query on every viewport change, real or emulated; the
      // lg (1024px, emitted by Tailwind as `@media (min-width:64rem)`) is the single boundary.
      // The JS only mirrors its negation for the static slot and closes the drawer on a crossing.
      // Only crossing the breakpoint closes the drawer: a viewport change that stays
      // inside the same mode (an on-screen keyboard, say) must leave it open.
      if (next !== lastMobile.current) setDrawerOpen(false);
      lastMobile.current = next;
      setIsMobile(next);
    };

    sync();
    window.addEventListener("resize", sync);
    return () => window.removeEventListener("resize", sync);
  }, []);

  // Picking a client or a session is navigation and must close the drawer.
  useEffect(() => {
    setDrawerOpen(false);
  }, [selectedClientId, selectedSessionId]);

  const sidebar = (
    <DashboardSidebar
      viewMode={viewMode}
      activeTab={activeTab}
      onViewModeChange={onViewModeChange}
      onTabChange={onTabChange}
    />
  );

  return (
    <div className="flex h-screen flex-col lg:flex-row">
      {!isMobile && <div className="hidden lg:flex">{sidebar}</div>}
      <Sheet open={drawerOpen} onOpenChange={setDrawerOpen}>
        <header className="flex h-14 shrink-0 items-center gap-3 border-b border-sidebar-border bg-sidebar px-3 lg:hidden">
          <SheetTrigger asChild>
            <button type="button" aria-label="Open navigation" className="inline-flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-sidebar-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring">
              <Menu className="h-5 w-5" aria-hidden="true" />
            </button>
          </SheetTrigger>
          <span className="font-semibold">ALICE</span>
        </header>
        <div className="flex min-w-0 flex-1 flex-col">{children}</div>
        <SheetContent side="left" className="w-64 max-w-[85vw] gap-0 p-0">
          <SheetTitle className="sr-only">Navigation</SheetTitle>
          <SheetDescription className="sr-only">Client, case and session navigation.</SheetDescription>
          {sidebar}
        </SheetContent>
      </Sheet>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import dynamic from "next/dynamic";
import {
  Loader2,
  AlertCircle,
} from "lucide-react";
import { CLINICAL_AI_API_BASE as API_BASE } from "@/lib/clinical-ai-api";
import { apiFetch } from "@/lib/auth";
import { Client } from "@/types";
import { useClientNavStore, type Session } from "@/stores/useClientNavStore";

const VignetteGenerator = dynamic(() => import("./vignette-generator"), {
  ssr: false,
});

/** `GET /sessions?clientId=` row (`formatSessionRow`, backend/CloudFlare.js:2469): the app's
 *  Session plus the DB timestamp the History tab renders. */
type Vignette = Session & { created_at: string | null };

export function MainContent({
  client,
  onChangeClient,
}: {
  client: Client;
  onChangeClient: () => void;
}) {
  const [savedVignettes, setSavedVignettes] = useState<Vignette[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState("generate");

  const CLIENT_ID = client.id.toString();

  const selectedCaseId = useClientNavStore((s) => s.selectedCaseId);
  const selectedSessionId = useClientNavStore((s) => s.selectedSessionId);

  // ✅ SAFE selectedSession (FIXED)
  const selectedSession = useClientNavStore((s) => {
    if (!s.client || !s.selectedCaseId || !s.selectedSessionId) {
      return null;
    }

    const cases = s.client.cases || [];
    const caseData = cases.find((c) => c.id === s.selectedCaseId);

    const sessions = caseData?.sessions || [];

    return (
      sessions.find((sess) => sess.id === s.selectedSessionId) || null
    );
  });

  const fetchVignettes = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const res = await apiFetch(
        `${API_BASE}/sessions?clientId=${client.id}`
      );

      const data = await res.json();

      if (Array.isArray(data)) {
        setSavedVignettes(data);
      } else if (data) {
        setSavedVignettes([data]);
      } else {
        setSavedVignettes([]);
      }
    } catch (err) {
      console.error("Fetch error:", err);
      setError("Failed to load sessions");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchVignettes();
  }, [client.id, selectedSessionId]);

  return (
    <main className="flex-1 min-w-0 space-y-6 p-4 sm:p-6">

      {/* HEADER */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b pb-4">
        <h1 className="text-xl font-bold min-w-0 break-words">
          {client.name} Dashboard
        </h1>

        <Button
          variant="outline"
          size="sm"
          onClick={onChangeClient}
          className="shrink-0"
        >
          Change Client
        </Button>
      </div>

      {/* ERROR */}
      {error && (
        <div className="flex items-center gap-2 rounded-md border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900 dark:border-amber-900/50 dark:bg-amber-950/40 dark:text-amber-200">
          <AlertCircle className="h-4 w-4" />
          <span>{error}</span>
        </div>
      )}

      <Tabs value={tab} onValueChange={setTab}>

        <TabsList>
          <TabsTrigger value="generate">Session</TabsTrigger>
          <TabsTrigger value="history">History</TabsTrigger>
          <TabsTrigger value="settings">Settings</TabsTrigger>
        </TabsList>

        {/* SESSION TAB */}
        <TabsContent value="generate">
          {selectedCaseId && selectedSessionId ? (
            <VignetteGenerator
              key={selectedSessionId}
              clientId={CLIENT_ID}
              caseId={selectedCaseId}
              sessionId={selectedSessionId}
              sessionName={selectedSession?.name}
            />
          ) : (
            <Card>
              <CardContent className="py-10 text-center">
                Select a session in the sidebar
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* HISTORY TAB */}
        <TabsContent value="history">
          <Card>
            <CardHeader>
              <CardTitle>History</CardTitle>
            </CardHeader>

            <CardContent>
              {isLoading ? (
                <Loader2 className="animate-spin" />
              ) : savedVignettes.length === 0 ? (
                <p className="text-sm text-muted-foreground">No data yet</p>
              ) : (
                <div className="space-y-2">
                  {savedVignettes.map((entry, i) => (
                    <div
                      key={i}
                      className="rounded-lg border p-3 text-sm break-words"
                    >
                      {entry.created_at || "No date"}
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* SETTINGS TAB */}
        <TabsContent value="settings">
          <Card>
            <CardHeader>
              <CardTitle>Config</CardTitle>
            </CardHeader>

            <CardContent className="space-y-1 text-sm text-muted-foreground">
              <p className="break-all">API: {API_BASE}</p>
              <p className="break-words">Client: {CLIENT_ID}</p>
            </CardContent>
          </Card>
        </TabsContent>

      </Tabs>

    </main>
  );
}

