"use client";

/**
 * components/tasks/DynamicTaskForm.tsx
 *
 * Typeform-inspired progressive-disclosure form orchestrating the two
 * practice-task handouts:
 *
 *   task_type "activity_log"  → Handout 1  (Weekly Activity Schedule)
 *   task_type "thought_record"→ Handout 10 (The 3 C's Practice Worksheet)
 *
 * ─── Auto-save strategy ──────────────────────────────────────────────────
 * Every data change is debounced (1 200 ms). The debounced handler calls
 * the Worker via apiFetch (lib/auth.ts) — NEVER localStorage / sessionStorage.
 * On failure the save-error banner is shown and form progression is blocked
 * until a subsequent auto-save succeeds (connection restored).
 *
 * `persist={false}` opts out entirely: no auto-save, no save badge, no
 * "Submit for review" and no network calls at all. Used by the signed-link
 * client page (app/practice/[sessionId]), whose caller has no bearer token.
 *
 * ─── Clinical safeguards ─────────────────────────────────────────────────
 * "Submit for review" is disabled until:
 *   (a) at least one auto-save has succeeded (submissionId is established)
 *   (b) there are no pending / in-flight saves
 *   (c) there is no outstanding save error
 * A mandatory Human Approval banner is shown before the final commit so
 * the client cannot accidentally submit (APP 8 / TGA).
 *
 * ─── Architecture ────────────────────────────────────────────────────────
 * This is a client component. It calls the Cloudflare Worker directly via
 * apiFetch — same pattern as vignette-generator.tsx and client-view.tsx.
 * lib/tasks.ts uses "use server" and cannot be imported here.
 * ─────────────────────────────────────────────────────────────────────────
 */

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useTransition,
} from "react";
import { cn } from "@/lib/utils";
import { apiFetch } from "@/lib/auth";
import { CLINICAL_AI_API_BASE } from "@/lib/clinical-ai-api";

import {
  AlertTriangle,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Cloud,
  CloudOff,
  Loader2,
  Send,
  ShieldCheck,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";

import {
  ActivityScheduleForm,
  createEmptySchedule,
  type WeeklySchedule,
} from "./ActivityScheduleForm";

import {
  ThreeCsForm,
  createEmptyThreeCsData,
  type ThreeCsData,
} from "./ThreeCsForm";

import {
  TwoChoiceWorksheetForm,
  createEmptyTwoChoiceData,
  type TwoChoiceData,
} from "./TwoChoiceWorksheetForm";

import type {
  FormData,
  ActivityLogFormData,
  ThoughtRecordFormData,
  TwoChoiceWorksheetFormData,
  NormalisedSubmission,
  UUID,
} from "@/types/tasks";

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

export type TaskVariant = "activity_log" | "thought_record" | "two_choice_worksheet";

interface DynamicTaskFormProps {
  /** Identifies the owning client for the submission. */
  clientId?: UUID;
  /** Practitioner to attribute the submission to. */
  practitionerId?: UUID;
  /** Which handout to render. */
  taskType: TaskVariant;
  /** Optional existing submissionId — pass when resuming a saved draft. */
  initialSubmissionId?: UUID;
  /** Optional submissionId alias matching initialSubmissionId. */
  submissionId?: string | null;
  /** Pre-populated task payload from the AI generator. */
  initialData?: any;
  /** Called after a successful final commit. */
  onSubmitted?: (submission: NormalisedSubmission) => void;
  /** Called when the user cancels. */
  onCancel?: () => void;
  /**
   * Defaults to `true`. When `false` the form is fill-in only: no auto-save,
   * no save badge, no submission id required to navigate, and no
   * "Submit for review" — nothing is sent anywhere.
   */
  persist?: boolean;
}

type SaveStatus = "idle" | "saving" | "saved" | "error";

// ---------------------------------------------------------------------------
// Save-status indicator
// ---------------------------------------------------------------------------
function SaveStatusBadge({ status }: { status: SaveStatus }) {
  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium transition-all",
        status === "idle" && "text-muted-foreground",
        status === "saving" && "bg-amber-100 text-amber-700 dark:bg-amber-950/40 dark:text-amber-300",
        status === "saved" && "bg-emerald-100 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300",
        status === "error" && "bg-rose-100 text-rose-700 dark:bg-rose-950/40 dark:text-rose-300"
      )}
    >
      {status === "idle" && <Cloud className="h-3.5 w-3.5" />}
      {status === "saving" && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
      {status === "saved" && <CheckCircle2 className="h-3.5 w-3.5" />}
      {status === "error" && <CloudOff className="h-3.5 w-3.5" />}

      {status === "idle" && <span>Draft</span>}
      {status === "saving" && <span>Saving…</span>}
      {status === "saved" && <span>Saved</span>}
      {status === "error" && <span>Save failed</span>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Error banner (blocks progression)
// ---------------------------------------------------------------------------
interface ErrorBannerProps {
  message: string;
  onRetry: () => void;
  isRetrying: boolean;
}

function ErrorBanner({ message, onRetry, isRetrying }: ErrorBannerProps) {
  return (
    <div
      role="alert"
      aria-live="assertive"
      className="flex flex-col gap-3 rounded-xl border border-rose-200 bg-rose-50 p-4 dark:border-rose-900 dark:bg-rose-950/40 sm:flex-row sm:items-center sm:justify-between"
    >
      <div className="flex items-start gap-3">
        <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-rose-600 dark:text-rose-400" />
        <div>
          <p className="text-sm font-semibold text-rose-800 dark:text-rose-200">
            Auto-save failed — your progress is not saved
          </p>
          <p className="mt-0.5 text-xs text-rose-700/80 dark:text-rose-300/80">
            {message}
          </p>
          <p className="mt-1 text-xs text-rose-700/80 dark:text-rose-300/80">
            Form progression is paused until the connection is restored. Do not
            close this tab.
          </p>
        </div>
      </div>
      <Button
        variant="outline"
        size="sm"
        onClick={onRetry}
        disabled={isRetrying}
        className="shrink-0 border-rose-300 text-rose-700 hover:bg-rose-100 dark:border-rose-800 dark:text-rose-300 dark:hover:bg-rose-900"
      >
        {isRetrying ? (
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
        ) : (
          "Retry now"
        )}
      </Button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Human-approval gate (shown before final submit)
// ---------------------------------------------------------------------------
interface ApprovalGateProps {
  onConfirm: () => void;
  onCancel: () => void;
  isSubmitting: boolean;
}

function ApprovalGate({ onConfirm, onCancel, isSubmitting }: ApprovalGateProps) {
  const [agreed, setAgreed] = useState(false);

  return (
    <div className="rounded-xl border border-primary/30 bg-primary/5 p-6 space-y-4">
      <div className="flex items-center gap-3">
        <ShieldCheck className="h-6 w-6 text-primary shrink-0" />
        <div>
          <h3 className="text-base font-semibold">Ready to submit for review?</h3>
          <p className="text-sm text-muted-foreground mt-0.5">
            Your completed task will be sent to your practitioner for review.
            You won&apos;t be able to edit it after submission.
          </p>
        </div>
      </div>

      <label className="flex items-start gap-3 cursor-pointer">
        <input
          type="checkbox"
          checked={agreed}
          onChange={(e) => setAgreed(e.target.checked)}
          className="mt-0.5 h-4 w-4 rounded-xs border-input accent-primary"
        />
        <span className="text-sm text-foreground">
          I confirm this is my completed work and I&apos;m ready for my
          practitioner to review it.
        </span>
      </label>

      <div className="flex gap-3">
        <Button
          variant="outline"
          size="sm"
          onClick={onCancel}
          disabled={isSubmitting}
          className="flex-1 sm:flex-none"
        >
          Go back
        </Button>
        <Button
          size="sm"
          onClick={onConfirm}
          disabled={!agreed || isSubmitting}
          className="flex-1 sm:flex-none gap-2"
        >
          {isSubmitting ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Send className="h-4 w-4" />
          )}
          Submit for review
        </Button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step-wizard shell for activity_log
// (The schedule is one big form; we split it into 3 "days" pages to avoid
// cognitive overload — Mon–Tue, Wed–Thu, Fri–Sun.)
// ---------------------------------------------------------------------------
const ACTIVITY_STEPS = [
  { label: "Mon – Tue", days: ["Mon", "Tue"] as const },
  { label: "Wed – Thu", days: ["Wed", "Thu"] as const },
  { label: "Fri – Sun", days: ["Fri", "Sat", "Sun"] as const },
];

// ---------------------------------------------------------------------------
// DynamicTaskForm (main export)
// ---------------------------------------------------------------------------
export function DynamicTaskForm({
  clientId = "",
  practitionerId = "00000000-0000-0000-0000-000000000000",
  taskType,
  initialSubmissionId,
  submissionId: externalSubmissionId,
  initialData,
  onSubmitted,
  onCancel,
  persist = true,
}: DynamicTaskFormProps) {

  // ── Wizard state ──────────────────────────────────────────────────────────
  const [wizardStep, setWizardStep] = useState(0);
  const totalSteps = taskType === "activity_log" ? ACTIVITY_STEPS.length : 1;

  // ── Form data ─────────────────────────────────────────────────────────────
  const [schedule, setSchedule] = useState<WeeklySchedule>(() => {
    const empty = createEmptySchedule();
    if (initialData?.activity_description) {
      try {
        const parsed = JSON.parse(initialData.activity_description);
        return { ...empty, ...parsed };
      } catch {
        return empty;
      }
    }
    return empty;
  });

  const [threeCsData, setThreeCsData] = useState<ThreeCsData>(() => {
    const empty = createEmptyThreeCsData();
    if (!initialData) return empty;
    return {
      situation: initialData.situation ?? empty.situation,
      automaticThought: initialData.automatic_thought ?? initialData.automaticThought ?? empty.automaticThought,
      emotions: initialData.emotions?.length ? initialData.emotions : empty.emotions,
      evidenceFor: initialData.evidence_for ?? initialData.evidenceFor ?? empty.evidenceFor,
      evidenceAgainst: initialData.evidence_against ?? initialData.evidenceAgainst ?? empty.evidenceAgainst,
      balancedThought: initialData.balanced_thought ?? initialData.balancedThought ?? empty.balancedThought,
      outcomeEmotionIntensity: initialData.outcome_emotion_intensity ?? initialData.outcomeEmotionIntensity ?? empty.outcomeEmotionIntensity,
    };
  });

  const [twoChoiceData, setTwoChoiceData] = useState<TwoChoiceData>(() => {
    const empty = createEmptyTwoChoiceData();
    if (!initialData || taskType !== "two_choice_worksheet") return empty;
    return {
      title: initialData.title ?? empty.title,
      prompts: initialData.prompts ?? empty.prompts,
      answers: initialData.answers ?? initialData.prompts?.map(() => null) ?? empty.answers,
      reflection: initialData.reflection ?? empty.reflection,
      reflection_prompt: initialData.reflection_prompt ?? empty.reflection_prompt,
      notes: initialData.notes ?? empty.notes,
    };
  });

  // ── Persistence state ─────────────────────────────────────────────────────
  const [submissionId, setSubmissionId] = useState<UUID | undefined>(
    initialSubmissionId ?? (externalSubmissionId || undefined)
  );

  useEffect(() => {
    if (externalSubmissionId) {
      setSubmissionId(externalSubmissionId);
    }
  }, [externalSubmissionId]);
  const [saveStatus, setSaveStatus] = useState<SaveStatus>("idle");
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isRetrying, setIsRetrying] = useState(false);

  // ── Commit state ──────────────────────────────────────────────────────────
  const [showApprovalGate, setShowApprovalGate] = useState(false);
  const [, startCommitTransition] = useTransition();
  const [isCommitting, setIsCommitting] = useState(false);
  const [committed, setCommitted] = useState(false);

  // ── Debounce ref ──────────────────────────────────────────────────────────
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // ── Build FormData payload from current state ─────────────────────────────
  const buildFormData = useCallback((): FormData => {
    if (taskType === "activity_log") {
      // Flatten WeeklySchedule to ActivityLogFormData for the first
      // non-empty entry as a representative; full grid is stored in notes.
      // Per types/tasks.ts, ActivityLogFormData has a single activity_date.
      // We store the full weekly grid as a JSON string in the notes field.
      const payload: ActivityLogFormData = {
        task_type: "activity_log",
        activity_date: new Date().toISOString().slice(0, 10),
        activity_description: JSON.stringify(schedule),
        pleasure_rating: 5,
        mastery_rating: 5,
        notes: "Weekly activity schedule — see activity_description for grid.",
      };
      return payload;
    } else if (taskType === "thought_record") {
      const payload: ThoughtRecordFormData = {
        task_type: "thought_record",
        situation: threeCsData.situation,
        automatic_thought: threeCsData.automaticThought,
        emotions: threeCsData.emotions.map((e) => ({
          label: e.label,
          intensity: e.intensity,
        })),
        evidence_for: threeCsData.evidenceFor,
        evidence_against: threeCsData.evidenceAgainst,
        balanced_thought: threeCsData.balancedThought,
        outcome_emotion_intensity: threeCsData.outcomeEmotionIntensity,
      };
      return payload;
    } else {
      const payload: TwoChoiceWorksheetFormData = {
        task_type: "two_choice_worksheet",
        title: twoChoiceData.title,
        prompts: twoChoiceData.prompts,
        answers: twoChoiceData.answers,
        reflection: twoChoiceData.reflection,
        reflection_prompt: twoChoiceData.reflection_prompt,
        notes: twoChoiceData.notes,
      };
      return payload;
    }
  }, [taskType, schedule, threeCsData, twoChoiceData]);

  // ── Core save function ────────────────────────────────────────────────────
  const performSave = useCallback(
    async (formData: FormData): Promise<boolean> => {
      // Fill-in-only mode: never touch the network.
      if (!persist) return false;

      setSaveStatus("saving");
      setSaveError(null);

      try {
        const res = await apiFetch(`${CLINICAL_AI_API_BASE}/tasks/submissions`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            id: submissionId ?? null,
            client_id: clientId,
            practitioner_id: practitionerId,
            task_type: taskType,
            form_data: formData,
          }),
        });

        if (!res.ok) {
          const body = await res.json().catch(() => null) as { error?: string } | null;
          throw new Error(body?.error ?? `HTTP ${res.status}`);
        }

        const row = await res.json() as { id: UUID };
        // Persist the returned id so subsequent saves update the same row.
        setSubmissionId((prev) => prev ?? row.id);
        setSaveStatus("saved");
        return true;
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Unknown error";
        setSaveError(msg);
        setSaveStatus("error");
        return false;
      }
    },
    [submissionId, clientId, practitionerId, taskType, persist]
  );

  // ── Debounced auto-save ───────────────────────────────────────────────────
  const triggerAutoSave = useCallback(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    // Mark as pending immediately so the UI reflects unsaved state
    setSaveStatus("saving");
    debounceRef.current = setTimeout(() => {
      performSave(buildFormData());
    }, 1200);
  }, [buildFormData, performSave]);

  // Schedule save whenever data changes
  useEffect(() => {
    if (!persist) return;
    triggerAutoSave();
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [schedule, threeCsData, twoChoiceData]);

  // ── Manual retry ─────────────────────────────────────────────────────────
  const handleRetry = useCallback(async () => {
    setIsRetrying(true);
    await performSave(buildFormData());
    setIsRetrying(false);
  }, [buildFormData, performSave]);

  // ── Navigation guards ─────────────────────────────────────────────────────
  // Without persistence there is no save state to wait on.
  const canProgress = !persist || saveStatus !== "error";
  const isLastStep = wizardStep === totalSteps - 1;

  // ── Final commit ──────────────────────────────────────────────────────────
  const handleCommit = useCallback(() => {
    if (!persist || !submissionId) return;
    setIsCommitting(true);

    startCommitTransition(async () => {
      try {
        const res = await apiFetch(
          `${CLINICAL_AI_API_BASE}/tasks/submissions/${encodeURIComponent(submissionId)}/commit`,
          { method: "POST", headers: { "Content-Type": "application/json" } }
        );

        if (!res.ok) {
          const body = await res.json().catch(() => null) as { error?: string } | null;
          throw new Error(body?.error ?? `HTTP ${res.status}`);
        }

        const submitted = await res.json() as NormalisedSubmission;
        setCommitted(true);
        onSubmitted?.(submitted);
      } catch (err) {
        const msg = err instanceof Error ? err.message : "Submit failed";
        setSaveError(msg);
        setSaveStatus("error");
        setShowApprovalGate(false);
      } finally {
        setIsCommitting(false);
      }
    });
  }, [submissionId, onSubmitted, startCommitTransition, persist]);

  // ── Progress bar ──────────────────────────────────────────────────────────
  const progressValue = useMemo(
    () => Math.round(((wizardStep + 1) / totalSteps) * 100),
    [wizardStep, totalSteps]
  );

  // ── Success screen ────────────────────────────────────────────────────────
  if (committed) {
    return (
      <div className="flex min-h-[50vh] flex-col items-center justify-center gap-6 px-6 py-12 text-center">
        <div className="flex h-20 w-20 items-center justify-center rounded-full bg-emerald-100 dark:bg-emerald-950">
          <CheckCircle2 className="h-10 w-10 text-emerald-600 dark:text-emerald-400" />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-bold">Task submitted!</h2>
          <p className="text-muted-foreground max-w-sm">
            Your practitioner will review your responses and get back to you.
            Great work completing this task.
          </p>
        </div>
        {onCancel && (
          <Button variant="outline" onClick={onCancel} size="lg">
            Return to dashboard
          </Button>
        )}
      </div>
    );
  }

  // ── Task title ────────────────────────────────────────────────────────────
  const taskTitle =
    taskType === "activity_log"
      ? "Weekly Activity Schedule"
      : taskType === "thought_record" 
      ? "The 3 C's Practice Worksheet"
      : "Interactive Worksheet";

  const taskSubtitle =
    taskType === "activity_log"
      ? "Track your activities and mood ratings across the week"
      : taskType === "thought_record"
      ? "Identify, examine, and reframe automatic thoughts"
      : "Make choices and reflect on your task";

  return (
    <div className="mx-auto max-w-4xl space-y-6 px-4 py-6 sm:px-6">

      {/* ── Header ──────────────────────────────────────────── */}
      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">{taskTitle}</h1>
            <p className="text-sm text-muted-foreground">{taskSubtitle}</p>
          </div>
          {persist && <SaveStatusBadge status={saveStatus} />}
        </div>

        {/* Progress bar */}
        {totalSteps > 1 && (
          <div className="space-y-1 pt-2">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span>{ACTIVITY_STEPS[wizardStep].label}</span>
              <span>
                {wizardStep + 1} / {totalSteps}
              </span>
            </div>
            <Progress value={progressValue} className="h-1.5" />
          </div>
        )}
      </div>

      {/* ── Save-error banner (blocks progression) ─────────── */}
      {saveStatus === "error" && saveError && (
        <ErrorBanner
          message={saveError}
          onRetry={handleRetry}
          isRetrying={isRetrying}
        />
      )}

      {/* ── Form body ────────────────────────────────────────── */}
      <div className="min-h-[400px]">
        {taskType === "activity_log" && (
          <ActivityScheduleForm
            schedule={schedule}
            onChange={setSchedule}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}

        {taskType === "thought_record" && (
          <ThreeCsForm
            data={threeCsData}
            onChange={setThreeCsData}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}

        {taskType === "two_choice_worksheet" && (
          <TwoChoiceWorksheetForm
            data={twoChoiceData}
            onChange={setTwoChoiceData}
            disabled={saveStatus === "error" || isCommitting}
          />
        )}
      </div>

      {/* ── Approval gate ────────────────────────────────────── */}
      {showApprovalGate && (
        <ApprovalGate
          onConfirm={handleCommit}
          onCancel={() => setShowApprovalGate(false)}
          isSubmitting={isCommitting}
        />
      )}

      {/* ── Navigation row ───────────────────────────────────── */}
      {!showApprovalGate && (
        <div className="flex items-center justify-between border-t border-border pt-4">
          {!persist && wizardStep === 0 && !onCancel ? (
            // Fill-in-only with no cancel handler: a "Cancel" would do nothing.
            <span aria-hidden="true" />
          ) : (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                if (wizardStep > 0) {
                  setWizardStep((s) => s - 1);
                } else {
                  onCancel?.();
                }
              }}
              className="gap-1.5"
            >
              <ChevronLeft className="h-4 w-4" />
              {wizardStep === 0 ? "Cancel" : "Back"}
            </Button>
          )}

          <div className="flex items-center gap-2">
            {/* Dot pagination (multi-step only) */}
            {totalSteps > 1 &&
              Array.from({ length: totalSteps }, (_, i) => (
                <span
                  key={i}
                  className={cn(
                    "h-1.5 rounded-full transition-all",
                    i === wizardStep
                      ? "w-5 bg-primary"
                      : "w-1.5 bg-muted-foreground/30"
                  )}
                />
              ))}
          </div>

          {isLastStep && !persist ? (
            // Fill-in-only: there is nothing to submit, so say so plainly.
            <p className="text-xs text-muted-foreground text-right">
              Answers on this page are not saved or sent.
            </p>
          ) : isLastStep ? (
            <Button
              size="sm"
              disabled={
                saveStatus === "error" ||
                saveStatus === "saving" ||
                !submissionId
              }
              onClick={() => setShowApprovalGate(true)}
              className="gap-1.5"
              title={
                !submissionId
                  ? "Waiting for first auto-save…"
                  : saveStatus === "error"
                  ? "Resolve save error before submitting"
                  : undefined
              }
            >
              <Send className="h-4 w-4" />
              Submit for review
            </Button>
          ) : (
            <Button
              size="sm"
              disabled={!canProgress}
              onClick={() => setWizardStep((s) => Math.min(s + 1, totalSteps - 1))}
              className="gap-1.5"
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

"use client"

import { useEffect, useRef, useState } from "react"
import { useClientNavStore } from "@/stores/useClientNavStore"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Textarea } from "@/components/ui/textarea"
import { Progress } from "@/components/ui/progress"
import {
  CheckCircle2,
  Copy,
  Download,
  Loader2,
  Sparkles,
  ClipboardPaste,
  BrainCircuit,
} from "lucide-react"
import {
  CLINICAL_AI_API_BASE as API_BASE,
  GROQ_TPM_LIMIT_NOTE,
  SESSION_NOTES_MAX_CHARS,
  SESSION_NOTES_WARN_CHARS,
  estimateTokens,
} from "@/lib/clinical-ai-api"
import { apiFetch } from "@/lib/auth"
import type { PracticePackage } from "@/lib/practice-package"
import { decideSessionHydration } from "@/lib/session-hydration"
import { upsertTaskDraft } from "@/lib/tasks"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { DynamicTaskForm } from "@/components/tasks/DynamicTaskForm"
import ReflectionCanvas from "@/components/canvas/ReflectionCanvas"
import { ModalitySelector } from "@/components/modality-selector"
import type { Modality } from "@/types/tasks"
import type { StructuredTask } from "@/lib/ai/schemas"

type StepId = 1 | 2 | 3

/**
 * `generatedTaskData` holds either the freshly generated structured task (enriched
 * with `homework` by `extractHomeworkList`) or the package hydrated from
 * `session.practicePackage` — the `practice_package` column carries both shapes.
 */
type StoredPracticeTask = StructuredTask | PracticePackage

const TASK_VARIANTS = ["activity_log", "thought_record", "reflection_prompt", "two_choice_worksheet"] as const

function isTaskVariant(v: string): v is (typeof TASK_VARIANTS)[number] {
  return (TASK_VARIANTS as readonly string[]).includes(v)
}

interface AnalysisResult {
  formulationId?: string
  inferredModality?: string
  riskFlags: unknown[]
  rationale: string
}

/** Must match the fallback string `handleAnalyze` returns in backend/CloudFlare.js. */
const PLACEHOLDER_RATIONALE = "Clinical synthesis unavailable."

function extractHomeworkList(task: StructuredTask & { homework?: string[] }): string[] {
  if (!task || typeof task !== "object") return []
  if (Array.isArray(task.homework) && task.homework.length > 0) {
    return task.homework
  }

  const items: string[] = []
  if (task.task_type === "two_choice_worksheet") {
    if (task.title) items.push(task.title)
    if (Array.isArray(task.prompts)) {
      task.prompts.forEach((p, idx: number) => {
        const q = typeof p === "string" ? p : p?.question
        if (q) items.push(`${idx + 1}. ${q}`)
      })
    }
    if (task.reflection_prompt) {
      items.push(`Reflection: ${task.reflection_prompt}`)
    }
  } else if (task.task_type === "thought_record") {
    items.push("Complete 3 C's Thought Record")
    if (task.situation) items.push(`Situation: ${task.situation}`)
    if (task.automatic_thought) items.push(`Catch It (Automatic Thought): ${task.automatic_thought}`)
    if (task.evidence_for || task.evidence_against) items.push("Check It: Review evidence for and against")
    if (task.balanced_thought) items.push(`Correct It (Balanced Thought): ${task.balanced_thought}`)
  } else if (task.task_type === "activity_log") {
    items.push("Weekly Activity Schedule")
    if (task.activity_description) items.push(`Scheduled Activity: ${task.activity_description}`)
    if (task.activity_date) items.push(`Target Date: ${task.activity_date}`)
    if (task.notes) items.push(`Notes: ${task.notes}`)
  } else if (task.task_type === "reflection_prompt") {
    items.push("Values & Defusion Canvas Reflection")
    if (task.prompt) items.push(task.prompt)
  }

  return items.length > 0 ? items : ["Complete assigned practice task"]
}

export default function VignetteGenerator({
  clientId,
  caseId,
  sessionId,
  sessionName,
}: {
  clientId: string
  caseId: string
  sessionId: string
  sessionName?: string
}) {
  const saveSessionContent = useClientNavStore((s) => s.saveSessionContent)
  /** Client name for the exported PDF header. */
  const clientName = useClientNavStore((s) => s.client?.name)

  const session = useClientNavStore((s) =>
    s.client?.cases.find((c) => c.id === caseId)
      ?.sessions.find((sess) => sess.id === sessionId)
  )

  /**
   * `GET /client/:id` embeds only `sessions(id,name)`, so the tree row is a stub
   * that shares this id without any payload — `sessionHydratedId` only matches
   * once `selectSession` has merged `GET /sessions/:id`. `hydratedSessionRef`
   * makes hydration one-shot per session, so later writes (blur-saves, renames,
   * the PATCH echo) can never reset the clinician's step.
   */
  const sessionHydratedId = useClientNavStore((s) => s.sessionHydratedId)
  const hydratedSessionRef = useRef<string | null>(null)

  const [step, setStep] = useState<StepId>(1)
  const [sessionInput, setSessionInput] = useState("")
  const [isProcessing, setIsProcessing] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [isSaving, setIsSaving] = useState(false)

  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null)
  const [practicePackage, setPracticePackage] = useState<PracticePackage | null>(null)

  const [selectedModalities, setSelectedModalities] = useState<Modality[]>(["CBT"])
  const [activityFormat, setActivityFormat] = useState<"activity_log" | "thought_record" | "reflection_prompt" | "two_choice_worksheet">("thought_record")
  const [generatedSubmissionId, setGeneratedSubmissionId] = useState<string | null>(null)
  const [generatedTaskData, setGeneratedTaskData] = useState<StoredPracticeTask | null>(null)

  const [degradedWarning, setDegradedWarning] = useState<string | null>(null)
  const [linkStatus, setLinkStatus] = useState<string | null>(null)

  /**
   * Groq's 8,000 tokens/minute ceiling is an *input* limit and the notes are sent
   * twice per run (analyze, then practice package), so an over-long paste is
   * rejected before it can burn the clinician's minute.
   */
  const notesLength = sessionInput.length
  const notesTokens = estimateTokens(notesLength)
  const notesTooLong = notesLength > SESSION_NOTES_MAX_CHARS
  const notesLong = !notesTooLong && notesLength > SESSION_NOTES_WARN_CHARS
  const notesBudget = `≈${notesTokens.toLocaleString()} tokens of Groq's 8,000/minute`

  useEffect(() => {
    if (!session) {
      hydratedSessionRef.current = null
      setDegradedWarning(null)
      setStep(1)
      setSessionInput("")
      setAnalysis(null)
      setPracticePackage(null)
      return
    }

    // `wait` while the tree stub is all we have (GET /client/:id carries only
    // `sessions(id,name)`), `keep` for a later store write — blur-save, rename, PATCH
    // echo — so the phase is never re-derived from anything but the real payload.
    const action = decideSessionHydration({
      sessionId: session.id,
      sessionHydratedId,
      latchedSessionId: hydratedSessionRef.current,
    })

    if (action !== "hydrate") return

    hydratedSessionRef.current = session.id
    setDegradedWarning(null)

    setSessionInput(session.sessionNotes || "")

    const storedAnalysis = session.analysis as AnalysisResult | null
    setAnalysis(storedAnalysis)

    const parseModalities = (raw?: string | null): Modality[] => {
      if (!raw) return ["CBT"];
      const valid: Modality[] = ["CBT", "ACT", "DBT"];
      const parsed = Array.from(
        new Set(
          raw
            .split(",")
            .map((m) => m.trim().toUpperCase() as Modality)
            .filter((m): m is Modality => valid.includes(m))
        )
      );
      return parsed.length > 0 ? parsed : ["CBT"];
    };

    if (session.modality) {
      setSelectedModalities(parseModalities(session.modality));
    } else if (storedAnalysis?.inferredModality) {
      setSelectedModalities(parseModalities(storedAnalysis.inferredModality));
    } else {
      setSelectedModalities(["CBT"]);
    }

    if (storedAnalysis?.rationale === PLACEHOLDER_RATIONALE) {
      setDegradedWarning(
        "This session still holds a placeholder analysis from an earlier failed run — regenerate to replace it."
      )
    }

    // Try to load practice package if in session (from GET /sessions/:id)
    if (session.practicePackage) {
      const pkg = session.practicePackage as any
      setPracticePackage(session.practicePackage)
      setGeneratedTaskData(pkg)
      if (pkg.task_type) {
        setActivityFormat(pkg.task_type)
      }
      setStep(2)
    } else {
      setPracticePackage(null)
      setGeneratedTaskData(null)
      setStep(1)
    }
  }, [session, sessionHydratedId])

  const persistNotes = async (notes: string) => {
    setIsSaving(true)
    try {
      await saveSessionContent(caseId, sessionId, { sessionNotes: notes })
    } finally {
      setIsSaving(false)
    }
  }

  const handleHeidiImport = async () => {
    try {
      const text = await navigator.clipboard.readText()
      if (text.length < 5) return alert("Clipboard is empty.")
      setSessionInput(text)
    } catch {
      alert("Please allow clipboard permissions.")
    }
  }

  /**
   * Programmatic A4 export (`lib/export-practice-pdf.ts`): vector text with
   * explicit page-boundary maths, so nothing overlaps or spills off the sheet.
   */
  const handleDownloadPdf = async () => {
    if (!practicePackage) {
      alert("Generate a practice package before exporting.")
      return
    }

    setIsExporting(true)
    try {
      const { downloadPracticePackagePdf } = await import("@/lib/export-practice-pdf")

      downloadPracticePackagePdf(practicePackage, {
        clientName,
        sessionName,
      })
    } catch (err) {
      console.error("❌ PDF EXPORT FAILED", err)
      alert(err instanceof Error ? err.message : "Could not export the PDF")
    } finally {
      setIsExporting(false)
    }
  }

  /**
   * Mints the single signed, expiring client link for the token-free practice
   * page. The Worker signs `v1|sessionId|exp` with `CLIENT_LINK_SECRET`, so the
   * raw session id alone no longer opens the client's material.
   */
  const handleCopyClientLink = async () => {
    setLinkStatus("Creating link…")

    try {
      const res = await apiFetch(`${API_BASE}/client-link/${sessionId}`)
      const data = await res.json().catch(() => null)

      if (!res.ok || !data?.practiceUrl) {
        throw new Error(data?.error || "Could not create a client link")
      }

      const url = data.practiceUrl as string

      await navigator.clipboard.writeText(url)

      setLinkStatus(
        `Copied the client link — expires ${new Date(
          data.expiresAt
        ).toLocaleDateString()}`
      )
    } catch (err) {
      setLinkStatus(
        err instanceof Error ? err.message : "Could not create a client link"
      )
    }
  }

  const handleAnalyzeAndGenerate = async () => {
    console.log("🚀 GENERATE CLICK", {
      clientId,
      caseId,
      sessionId,
      step,
      notesLength: sessionInput.length,
    })

    if (!sessionInput) {
      console.warn("⛔ GENERATE BLOCKED: session notes are empty")
      return
    }

    // Defence in depth: `sessionInput` can be hydrated from the database by
    // `useClientNavStore`, which bypasses the textarea's own guard.
    if (notesTooLong) {
      console.warn("⛔ GENERATE BLOCKED: notes exceed the Groq token budget", {
        notesLength,
        notesTokens,
      })
      alert(
        `These notes are ${notesLength.toLocaleString()} characters (${notesBudget}). ` +
          `${GROQ_TPM_LIMIT_NOTE} Trim them to about ${SESSION_NOTES_MAX_CHARS.toLocaleString()} ` +
          "characters, or split the session, then try again."
      )
      return
    }

    setIsProcessing(true)
    setDegradedWarning(null)
    try {
      // 1. Analyze
      const analyzeUrl = `${API_BASE}/analyze/session?allowDegraded=1`
      const analyzePayload = {
        sessionNotes: sessionInput,
        clientId,
        sessionId,
      }

      console.log("➡️ POST", analyzeUrl, analyzePayload)

      const analyzeRes = await apiFetch(analyzeUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(analyzePayload),
      })
      const analyzeText = await analyzeRes.text()
      if (!analyzeText) {
        throw new Error(`Server returned ${analyzeRes.status} with empty response`)
      }
      const analyzeData = JSON.parse(analyzeText)

      console.log("⬅️ RESPONSE", analyzeUrl, analyzeRes.status, analyzeData)
      if (!analyzeRes.ok) {
        throw new Error(
          (analyzeData?.detail || analyzeData?.error || "Analysis failed") +
          " (Status: " + analyzeRes.status + ", Data: " + JSON.stringify(analyzeData) + ")"
        )
      }

      setAnalysis(analyzeData)

      if (analyzeData?.degraded) {
        setDegradedWarning(analyzeData.warning || "AI analysis was unavailable.")
      }

      // 2. Generate Structured Task
      const genUrl = `${API_BASE}/generate/structured-task?allowDegraded=1`
      const cleanModalities = selectedModalities.map((m) => m.toUpperCase() as Modality)
      const genPayload = {
        sessionContext: sessionInput,
        activityFormat: "auto",
        modalities: cleanModalities,
      }

      console.log("➡️ POST", genUrl, genPayload)

      const genRes = await apiFetch(genUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(genPayload),
      })
      const genText = await genRes.text()
      if (!genText) {
        throw new Error(`Server returned ${genRes.status} with empty response`)
      }
      const taskData = JSON.parse(genText)

      console.log("⬅️ RESPONSE", genUrl, genRes.status, taskData)
      if (!genRes.ok) {
        throw new Error(
          taskData?.detail ||
            taskData?.error ||
            "Structured task generation failed"
        )
      }

      const derivedHomework = extractHomeworkList(taskData)
      const enrichedTaskData = {
        ...taskData,
        homework: derivedHomework,
      }

      setGeneratedTaskData(enrichedTaskData)
      setPracticePackage(enrichedTaskData as any)

      if (taskData?.degraded) {
        setDegradedWarning(taskData.warning || "AI generation was unavailable.")
      }

      // 3. Database Persistence: save draft
      const draft = await upsertTaskDraft({
        clientId,
        practitionerId: "00000000-0000-0000-0000-000000000000",
        taskType: activityFormat as any,
        formData: enrichedTaskData as any,
      })

      setGeneratedSubmissionId(draft.id)
      setActivityFormat(taskData.task_type || activityFormat)
      setStep(2)

      // 4. Save session content
      await saveSessionContent(caseId, sessionId, {
        sessionNotes: sessionInput,
        analysis: analyzeData,
        practicePackage: enrichedTaskData,
        homework: derivedHomework,
        modality: selectedModalities.join(", "),
      })
    } catch (err) {
      console.error(err)

      const message =
        err instanceof Error ? err.message : "Failed to generate structured task"

      /**
       * Groq's 429 body already says how long to wait ("Please try again in
       * 19.2525s"); surface that instead of a wall of text.
       */
      const retryIn = /try again in ([\d.]+)s/i.exec(message)

      alert(
        retryIn
          ? `Groq rate limit reached (8,000 tokens/minute). Try again in about ${Math.ceil(
              Number(retryIn[1])
            )} seconds, or shorten the notes.`
          : message
      )
    } finally {
      setIsProcessing(false)
    }
  }

  const handleRegenerateExplicit = async () => {
    console.log("🚀 REGENERATE CLICK", {
      activityFormat,
    })

    setIsProcessing(true)
    setDegradedWarning(null)
    try {
      const genUrl = `${API_BASE}/generate/structured-task?allowDegraded=1`
      const cleanModalities = selectedModalities.map((m) => m.toUpperCase() as Modality)
      const genPayload = {
        sessionContext: sessionInput,
        activityFormat,
        modalities: cleanModalities,
      }

      const genRes = await apiFetch(genUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(genPayload),
      })
      const genText = await genRes.text()
      if (!genText) {
        throw new Error(`Server returned ${genRes.status} with empty response`)
      }
      const taskData = JSON.parse(genText)

      if (!genRes.ok) {
        throw new Error(taskData?.detail || taskData?.error || "Structured task generation failed")
      }

      const derivedHomework = extractHomeworkList(taskData)
      const enrichedTaskData = {
        ...taskData,
        homework: derivedHomework,
      }

      setGeneratedTaskData(enrichedTaskData)
      setPracticePackage(enrichedTaskData as any)

      if (taskData?.degraded) {
        setDegradedWarning(taskData.warning || "AI generation was unavailable.")
      }

      const draft = await upsertTaskDraft({
        clientId,
        practitionerId: "00000000-0000-0000-0000-000000000000",
        taskType: activityFormat as any,
        formData: enrichedTaskData as any,
      })

      setGeneratedSubmissionId(draft.id)

      await saveSessionContent(caseId, sessionId, {
        practicePackage: enrichedTaskData,
        homework: derivedHomework,
      })
    } catch (err) {
      console.error(err)
      const message = err instanceof Error ? err.message : "Failed to generate structured task"
      const retryIn = /try again in ([\d.]+)s/i.exec(message)
      alert(retryIn ? `Groq rate limit reached. Try again in about ${Math.ceil(Number(retryIn[1]))} seconds.` : message)
    } finally {
      setIsProcessing(false)
    }
  }

  return (
    <Card className="max-w-2xl mx-auto shadow-2xl border-t-4 border-t-primary rounded-4xl overflow-hidden bg-card text-card-foreground">
      <CardHeader className="border-b border-border bg-muted/50 px-5 pb-6 sm:px-8">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-primary/10 rounded-xl">
              <BrainCircuit className="h-5 w-5 text-primary" />
            </div>
            <CardTitle className="text-xl font-black tracking-tight text-foreground uppercase">
              ALICE 
            </CardTitle>
          </div>
          <div className="flex flex-col items-end gap-1">
            {sessionName && (
              <span className="max-w-[12rem] truncate text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
                {sessionName}
              </span>
            )}
            <div className="px-3 py-1 rounded-full border border-border bg-background text-[10px] font-bold text-muted-foreground">
              PHASE {step}
              {isSaving ? " · saving…" : ""}
            </div>
          </div>
        </div>
        <Progress value={step * 33.3} className="mt-6 h-1.5 bg-muted" />
      </CardHeader>

      {degradedWarning && (
        <div className="mx-5 mt-6 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs font-medium text-amber-900 sm:mx-8 dark:border-amber-900/50 dark:bg-amber-950/40 dark:text-amber-200">
          ⚠️ AI unavailable: {degradedWarning}
        </div>
      )}

      <CardContent className="px-5 pt-8 pb-10 sm:px-8">
        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
            <div className="relative">
              <Textarea
                value={sessionInput}
                onChange={(e) => setSessionInput(e.target.value)}
                onBlur={() => {
                  if (sessionInput.trim()) persistNotes(sessionInput)
                }}
                placeholder="Paste Heidi notes here..."
                className="min-h-[220px] rounded-4xl border-2 bg-muted/50 p-6 text-base focus:border-primary/20"
              />
              <Button
                onClick={handleHeidiImport}
                variant="outline"
                size="sm"
                className="absolute top-4 right-4 rounded-full border-border bg-background shadow-sm"
              >
                <ClipboardPaste className="h-4 w-4 mr-2" /> Paste from Heidi
              </Button>
            </div>

            <div className="flex flex-col gap-2">
              <div
                aria-live="polite"
                className="flex items-center justify-between text-[11px] font-semibold uppercase tracking-wider"
              >
                <span className="text-muted-foreground">
                  {notesLength.toLocaleString()} /{" "}
                  {SESSION_NOTES_MAX_CHARS.toLocaleString()} characters ·{" "}
                  {notesBudget}
                </span>
                {notesTooLong ? (
                  <span className="text-destructive">Too long to send</span>
                ) : notesLong ? (
                  <span className="text-amber-600 dark:text-amber-400">Long note</span>
                ) : null}
              </div>

              {notesTooLong && (
                <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-xs font-medium text-red-900 dark:border-red-900/50 dark:bg-red-950/40 dark:text-red-200">
                  {GROQ_TPM_LIMIT_NOTE} Trim these notes to about{" "}
                  {SESSION_NOTES_MAX_CHARS.toLocaleString()} characters — as they
                  stand, the request is rejected before any AI work happens.
                </div>
              )}

              {notesLong && (
                <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs font-medium text-amber-900 dark:border-amber-900/50 dark:bg-amber-950/40 dark:text-amber-200">
                  {GROQ_TPM_LIMIT_NOTE} Generation should still work, but a second
                  run inside the same minute may be rate limited.
                </div>
              )}
            </div>

            <div className="space-y-4 py-4">
              <ModalitySelector 
                selectedModalities={selectedModalities}
                onChange={(mods) => {
                  setSelectedModalities(mods);
                }}
                disabled={isProcessing}
              />
            </div>

            <Button
              onClick={handleAnalyzeAndGenerate}
              className="h-14 w-full rounded-md text-lg font-bold shadow-lg"
              disabled={!sessionInput || isProcessing || notesTooLong}
            >
              {isProcessing ? (
                <Loader2 className="animate-spin mr-2" aria-hidden="true" />
              ) : (
                <Sparkles className="mr-2" aria-hidden="true" />
              )}
              Analyze & Recommend
            </Button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-in slide-in-from-right">
            <div className="rounded-4xl border border-blue-100 bg-blue-50/50 p-6 text-sm italic font-medium leading-relaxed text-blue-900 dark:border-blue-900/50 dark:bg-blue-950/30 dark:text-blue-200">
              {analysis?.rationale &&
              analysis.rationale !== PLACEHOLDER_RATIONALE
                ? `"${analysis.rationale}"`
                : `"No formulation yet — run Analyze & Recommend. (An earlier run stored no usable analysis.)"`}
            </div>

            <div className="p-6 border-2 rounded-4xl bg-white text-zinc-900 space-y-8 shadow-sm sm:p-10">
              <div className="flex flex-col gap-6 border-b pb-8">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-2xl font-black uppercase tracking-tight leading-none">
                      Client Practice Task
                    </h3>
                    <p className="text-[10px] font-black text-primary uppercase tracking-[0.3em] mt-3">
                      ALICE
                    </p>
                  </div>
                  <div className="flex h-10 w-10 items-center justify-center rounded-xl border border-green-100 bg-green-50 dark:border-green-900/50 dark:bg-green-950/40">
                    <CheckCircle2 className="h-6 w-6 text-green-600 dark:text-green-400" />
                  </div>
                </div>

                <div className="flex flex-col gap-3 rounded-xl border border-border bg-muted/50 p-4">
                  <div className="flex items-center justify-between">
                    <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
                      Override Activity Format
                    </label>
                  </div>
                  <div className="flex flex-col gap-3 sm:flex-row">
                    <Select
                      value={activityFormat}
                      onValueChange={(val: string) => {
                        if (isTaskVariant(val)) setActivityFormat(val)
                      }}
                      disabled={isProcessing}
                    >
                      <SelectTrigger className="h-12 flex-1 rounded-md border-input bg-background">
                        <SelectValue placeholder="Select activity format" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="activity_log">Activity Log (activity_log)</SelectItem>
                        <SelectItem value="thought_record">Thought Record (thought_record)</SelectItem>
                        <SelectItem value="two_choice_worksheet">Dual-Response Skills (two_choice_worksheet)</SelectItem>
                        <SelectItem value="reflection_prompt">Reflection Prompt (reflection_prompt)</SelectItem>
                      </SelectContent>
                    </Select>
                    <Button 
                      onClick={handleRegenerateExplicit}
                      disabled={isProcessing}
                      variant="outline"
                      className="h-12 rounded-md border-input bg-background px-6"
                    >
                      {isProcessing ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" /> : <Sparkles className="h-4 w-4 mr-2 text-primary" aria-hidden="true" />}
                      {isProcessing ? "Generating..." : "Regenerate"}
                    </Button>
                  </div>
                </div>
              </div>

              {activityFormat === "reflection_prompt" ? (
                <ReflectionCanvas
                  clientId={clientId}
                  submissionId={generatedSubmissionId}
                />
              ) : (
                <DynamicTaskForm
                  clientId={clientId}
                  taskType={activityFormat}
                  initialData={generatedTaskData}
                  submissionId={generatedSubmissionId}
                />
              )}
            </div>
            
            <div className="rounded-xl border border-border bg-muted/50 p-4 space-y-3">
              <div className="text-[10px] font-black text-muted-foreground uppercase tracking-widest">
                Client link · signed &amp; expiring
              </div>

              <div className="flex gap-3">
                <Button
                  variant="outline"
                  onClick={handleCopyClientLink}
                  className="w-full h-11 rounded-md font-bold"
                >
                  <Copy className="h-4 w-4 mr-2" aria-hidden="true" /> Copy Client Link
                </Button>
              </div>

              {linkStatus && (
                <div className="text-[11px] font-medium text-muted-foreground">
                  {linkStatus}
                </div>
              )}
            </div>

            <div className="flex flex-col gap-3 sm:flex-row">
              <Button
                variant="outline"
                onClick={() => setStep(1)}
                className="h-12 rounded-md"
              >
                Back to Notes
              </Button>
              <Button
                onClick={handleDownloadPdf}
                className="h-12 flex-1 rounded-md bg-foreground font-bold text-background hover:bg-foreground/90"
                disabled={isExporting || !practicePackage}
              >
                {isExporting ? (
                  <Loader2 className="animate-spin mr-2" aria-hidden="true" />
                ) : (
                  <Download className="mr-2" aria-hidden="true" />
                )}
                Export PDF
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import { useCallback, useEffect, useLayoutEffect, useMemo, useState } from "react"
import {
  type ClinicalHierarchy,
  addCase,
  addClient,
  addSession,
  appendSessionAnalysis,
  appendSessionWorksheet,
  findCase,
  findClient,
  findSession,
  loadClinicalHierarchy,
  saveClinicalHierarchy,
  updateSessionNotes,
} from "@/lib/clinical-hierarchy"

export function useClinicalWorkspace() {
  const [hierarchy, setHierarchy] = useState<ClinicalHierarchy>(() => loadClinicalHierarchy())
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [selectedCaseId, setSelectedCaseId] = useState<string | null>(null)
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null)

  useEffect(() => {
    saveClinicalHierarchy(hierarchy)
  }, [hierarchy])

  useLayoutEffect(() => {
    if (hierarchy.clients.length === 0) return
    if (selectedClientId && findClient(hierarchy, selectedClientId)) return
    const c = hierarchy.clients[0]
    setSelectedClientId(c.id)
    setSelectedCaseId(c.cases[0]?.id ?? null)
    setSelectedSessionId(c.cases[0]?.sessions[0]?.id ?? null)
  }, [hierarchy, selectedClientId])

  const selectClient = useCallback(
    (id: string) => {
      const c = findClient(hierarchy, id)
      if (!c) return
      setSelectedClientId(id)
      const firstCase = c.cases[0]
      setSelectedCaseId(firstCase?.id ?? null)
      setSelectedSessionId(firstCase?.sessions[0]?.id ?? null)
    },
    [hierarchy],
  )

  const selectCase = useCallback(
    (id: string) => {
      if (!selectedClientId) return
      const k = findCase(hierarchy, selectedClientId, id)
      if (!k) return
      setSelectedCaseId(id)
      setSelectedSessionId(k.sessions[0]?.id ?? null)
    },
    [hierarchy, selectedClientId],
  )

  const selectCasePath = useCallback(
    (clientId: string, caseId: string) => {
      const k = findCase(hierarchy, clientId, caseId)
      if (!k) return
      setSelectedClientId(clientId)
      setSelectedCaseId(caseId)
      setSelectedSessionId(k.sessions[0]?.id ?? null)
    },
    [hierarchy],
  )

  const selectSession = useCallback((id: string) => {
    setSelectedSessionId(id)
  }, [])

  const selectSessionPath = useCallback(
    (clientId: string, caseId: string, sessionId: string) => {
      setSelectedClientId(clientId)
      setSelectedCaseId(caseId)
      setSelectedSessionId(sessionId)
    },
    [],
  )

  const onAddClient = useCallback((label: string) => {
    let newClientId = ""
    let newCaseId: string | null = null
    let newSessionId: string | null = null
    setHierarchy((h) => {
      const next = addClient(h, label)
      const added = next.clients[next.clients.length - 1]
      newClientId = added.id
      newCaseId = added.cases[0]?.id ?? null
      newSessionId = added.cases[0]?.sessions[0]?.id ?? null
      return next
    })
    setSelectedClientId(newClientId)
    setSelectedCaseId(newCaseId)
    setSelectedSessionId(newSessionId)
  }, [])

  const onAddCase = useCallback(
    (label: string) => {
      if (!selectedClientId) return
      let newCaseId = ""
      let newSessionId: string | null = null
      setHierarchy((h) => {
        const next = addCase(h, selectedClientId, label)
        const c = findClient(next, selectedClientId)
        const added = c?.cases[c.cases.length - 1]
        if (added) {
          newCaseId = added.id
          newSessionId = added.sessions[0]?.id ?? null
        }
        return next
      })
      if (newCaseId) {
        setSelectedCaseId(newCaseId)
        setSelectedSessionId(newSessionId)
      }
    },
    [selectedClientId],
  )

  const onAddSession = useCallback(
    (label: string) => {
      if (!selectedClientId || !selectedCaseId) return
      let newSessionId = ""
      setHierarchy((h) => {
        const next = addSession(h, selectedClientId, selectedCaseId, label)
        const k = findCase(next, selectedClientId, selectedCaseId)
        const added = k?.sessions[k.sessions.length - 1]
        if (added) newSessionId = added.id
        return next
      })
      if (newSessionId) setSelectedSessionId(newSessionId)
    },
    [selectedClientId, selectedCaseId],
  )

  const onAddSessionForCase = useCallback(
    (clientId: string, caseId: string, label: string) => {
      let newSessionId = ""
      setHierarchy((h) => {
        const next = addSession(h, clientId, caseId, label)
        const k = findCase(next, clientId, caseId)
        const added = k?.sessions[k.sessions.length - 1]
        if (added) newSessionId = added.id
        return next
      })
      setSelectedClientId(clientId)
      setSelectedCaseId(caseId)
      if (newSessionId) setSelectedSessionId(newSessionId)
    },
    [],
  )

  const persistSessionNotes = useCallback(
    (notes: string) => {
      if (!selectedClientId || !selectedCaseId || !selectedSessionId) return
      setHierarchy((h) =>
        updateSessionNotes(h, selectedClientId, selectedCaseId, selectedSessionId, notes),
      )
    },
    [selectedClientId, selectedCaseId, selectedSessionId],
  )

  const persistSessionAnalysis = useCallback(
    (analysis: {
      notesSnapshot: string
      inferredModality?: string
      rationale: string
      riskFlags: unknown[]
    }) => {
      if (!selectedClientId || !selectedCaseId || !selectedSessionId) return
      setHierarchy((h) =>
        appendSessionAnalysis(
          h,
          selectedClientId,
          selectedCaseId,
          selectedSessionId,
          analysis,
        ),
      )
    },
    [selectedClientId, selectedCaseId, selectedSessionId],
  )

  const persistSessionWorksheet = useCallback(
    (worksheet: {
      modality: string
      scenario: string
      quiz: string[]
      homework: string[]
    }) => {
      if (!selectedClientId || !selectedCaseId || !selectedSessionId) return
      setHierarchy((h) =>
        appendSessionWorksheet(
          h,
          selectedClientId,
          selectedCaseId,
          selectedSessionId,
          worksheet,
        ),
      )
    },
    [selectedClientId, selectedCaseId, selectedSessionId],
  )

  const sessionNotes = useMemo(() => {
    if (!selectedClientId || !selectedCaseId || !selectedSessionId) return ""
    return (
      findSession(hierarchy, selectedClientId, selectedCaseId, selectedSessionId)?.notes ?? ""
    )
  }, [hierarchy, selectedClientId, selectedCaseId, selectedSessionId])

  const selectedSession = useMemo(() => {
    if (!selectedClientId || !selectedCaseId || !selectedSessionId) return undefined
    return findSession(hierarchy, selectedClientId, selectedCaseId, selectedSessionId)
  }, [hierarchy, selectedClientId, selectedCaseId, selectedSessionId])

  const sessionContextKey = useMemo(() => {
    if (!selectedClientId || !selectedCaseId || !selectedSessionId) return ""
    return `${selectedClientId}:${selectedCaseId}:${selectedSessionId}`
  }, [selectedClientId, selectedCaseId, selectedSessionId])

  return {
    hierarchy,
    selectedClientId,
    selectedCaseId,
    selectedSessionId,
    selectClient,
    selectCase,
    selectCasePath,
    selectSession,
    selectSessionPath,
    onAddClient,
    onAddCase,
    onAddSession,
    onAddSessionForCase,
    persistSessionNotes,
    persistSessionAnalysis,
    persistSessionWorksheet,
    sessionNotes,
    selectedSession,
    sessionContextKey,
    clientIdForApi: selectedClientId ?? "",
  }
}

export type ClinicalWorkspace = ReturnType<typeof useClinicalWorkspace>

import * as React from 'react'

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener('change', onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener('change', onChange)
  }, [])

  return !!isMobile
}
